from __future__ import annotations; from pathlib import Path; from common.testing import audit_router_contracts as audit; ROOT = Path(__file__).resolve().parents[2]
def test_detects_endpoint_without_response_model(tmp_path: Path) -> None: router = tmp_path / 'apps' / 'backend' / 'src' / 'routers' / 'demo.py'; router.parent.mkdir(parents=True); router.write_text('\nfrom fastapi import APIRouter\n\nrouter = APIRouter()\n\n\n@router.get("/typed", response_model=int)\nasync def typed() -> int:\n    return 1\n\n\n@router.post("/untyped")\nasync def untyped():\n    return {"x": 1}\n'.lstrip(), encoding='utf-8'); findings = audit.scan_dir(tmp_path / 'apps' / 'backend' / 'src' / 'routers', repo_root=tmp_path); assert len(findings) == 1; assert findings[0].handler == 'untyped'; assert findings[0].method == 'POST'; assert findings[0].route == '/untyped'; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); _m1_router = _m1_tmp / 'demo.py'; _m1_router.write_text('from fastapi import APIRouter\nrouter = APIRouter()\n\n\n@router.get("/none", response_model=None)\nasync def none_handler():\n    return {}\n', encoding='utf-8'); _m1_findings = audit.scan_file(_m1_router, repo_root=_m1_tmp); assert len(_m1_findings) == 1 and _m1_findings[0].handler == 'none_handler'; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _m2_router = _m2_tmp / 'demo.py'; _m2_router.write_text('from fastapi import APIRouter\nrouter = APIRouter()\nconflicts_router = APIRouter(prefix="/review")\n\n\n@conflicts_router.delete("/{conflict_id}")\nasync def drop_conflict():\n    return None\n', encoding='utf-8'); _m2_findings = audit.scan_file(_m2_router, repo_root=_m2_tmp); assert len(_m2_findings) == 1 and _m2_findings[0].handler == 'drop_conflict'; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); _m3_router = _m3_tmp / 'demo.py'; _m3_router.write_text('from fastapi import APIRouter\nrouter = APIRouter()\n\n\n@router.trace("/p")\nasync def probe():\n    return {}\n', encoding='utf-8'); assert [_m3_f.method for _m3_f in audit.scan_file(_m3_router, repo_root=_m3_tmp)] == ['TRACE']; _m4_tmp = tmp_path / '_m4'; _m4_tmp.mkdir(exist_ok=True); _m4_router = _m4_tmp / 'apps' / 'backend' / 'src' / 'routers' / 'demo.py'; _m4_router.parent.mkdir(parents=True); _m4_router.write_text('\nfrom fastapi import APIRouter\n\nrouter = APIRouter()\n\n\n@router.delete("/a")\nasync def a():\n    return None\n'.lstrip(), encoding='utf-8'); _m4_exit_code = audit.main(['--repo-root', str(_m4_tmp), '--router-dir', str(_m4_router.parent), '--max-allowed', '0', '--check']); assert _m4_exit_code == 1; _m5_tmp = tmp_path / '_m5'; _m5_tmp.mkdir(exist_ok=True); _m5_router = _m5_tmp / 'demo.py'; _m5_router.write_text("from fastapi import APIRouter\nrouter = APIRouter()\n_p = '/dyn'\n\n\n@router.get(_p)\nasync def dyn():\n    return {}\n", encoding='utf-8'); _m5_findings = audit.scan_file(_m5_router, repo_root=Path('/some/other/root')); assert len(_m5_findings) == 1; assert _m5_findings[0].route == '?'; assert _m5_findings[0].relative_path == _m5_router.as_posix()
def test_real_repo_within_budget() -> None: findings = audit.scan_dir(ROOT / 'apps' / 'backend' / 'src' / 'routers', repo_root=ROOT); assert len(findings) <= audit.DEFAULT_MAX_UNTYPED_ENDPOINTS, [f'{f.relative_path}:{f.line} {f.method} {f.route}' for f in findings]
def test_findings_doc_is_in_sync() -> None: findings = audit.scan_dir(ROOT / 'apps' / 'backend' / 'src' / 'routers', repo_root=ROOT); expected = audit.render_markdown(findings); doc = (ROOT / 'docs' / 'reference' / 'router-contract-maturity.md').read_text(encoding='utf-8'); assert doc == expected, 'Run: python tools/audit_router_contracts.py --output docs/reference/router-contract-maturity.md'; from tools import audit_router_contracts as wrapper; assert wrapper.main is audit.main
def test_cli_writes_output_and_reports_within_budget(tmp_path: Path, capsys) -> None: routers = tmp_path / 'routers'; routers.mkdir(); (routers / 'demo.py').write_text('from fastapi import APIRouter\nrouter = APIRouter()\n\n\n@router.get("/ok", response_model=int)\nasync def ok() -> int:\n    return 1\n', encoding='utf-8'); out = tmp_path / 'findings.md'; code = audit.main(['--repo-root', str(tmp_path), '--router-dir', str(routers), '--output', str(out)]); assert code == 0; assert out.exists() and 'Untyped Endpoints' in out.read_text(encoding='utf-8'); assert 'Untyped endpoints: 0' in capsys.readouterr().out
